package com.rekluzlabs.makokolorize.ui.screensimport android.net.Uriimport androidx.activity.ComponentActivityimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.navigationBarsPaddingimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.layout.widthimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.ArrowDropDownimport androidx.compose.material.icons.filled.CheckCircleimport androidx.compose.material.icons.outlined.Circleimport androidx.compose.material3.Buttonimport androidx.compose.material3.ButtonDefaultsimport androidx.compose.material3.Cardimport androidx.compose.material3.CardDefaultsimport androidx.compose.material3.CircularProgressIndicatorimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.FilterChipimport androidx.compose.material3.FilterChipDefaultsimport androidx.compose.material3.HorizontalDividerimport androidx.compose.material3.Iconimport androidx.compose.material3.LinearProgressIndicatorimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.OutlinedButtonimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.getValueimport androidx.compose.runtime.rememberimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.text.font.FontWeightimport androidx.lifecycle.ViewModelProviderimport androidx.compose.ui.text.style.TextAlignimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport coil.compose.AsyncImageimport com.rekluzlabs.makokolorize.data.image.ImageRepositoryimport com.rekluzlabs.makokolorize.domain.ColorizeUseCaseimport com.rekluzlabs.makokolorize.domain.RunConfigimport com.rekluzlabs.makokolorize.ui.viewmodel.RestoreEffectimport com.rekluzlabs.makokolorize.ui.viewmodel.RestoreUiEventimport com.rekluzlabs.makokolorize.ui.viewmodel.RestoreUiStateimport com.rekluzlabs.makokolorize.ui.viewmodel.RestoreViewModelimport com.rekluzlabs.makokolorize.ui.viewmodel.RestoreViewModelFactory@OptIn(ExperimentalMaterial3Api::class)@Composablefun RestoreRoute(    imageUri: Uri,    onResultReady: (Uri) -> Unit,    onBack: () -> Unit,) {    val context = LocalContext.current    val owner = context as ComponentActivity    val factory = remember(imageUri) {        RestoreViewModelFactory(            imageRepository = ImageRepository(context),            colorizeUseCase = ColorizeUseCase(context),            imageUri = imageUri        )    }    val viewModel = remember(owner, imageUri) {        ViewModelProvider(owner, factory)[            "restore_$imageUri", RestoreViewModel::class.java        ]    }    val state by viewModel.state.collectAsState()    LaunchedEffect(Unit) {        viewModel.effects.collect { effect ->            when (effect) {                is RestoreEffect.NavigateToResult -> onResultReady(effect.resultUri)            }        }    }    RestoreContent(        state = state,        onEvent = viewModel::onEvent,        onBack = onBack    )}@OptIn(ExperimentalMaterial3Api::class)@Composableprivate fun RestoreContent(    state: RestoreUiState,    onEvent: (RestoreUiEvent) -> Unit,    onBack: () -> Unit,) {    Box(modifier = Modifier.fillMaxSize()) {        Column(modifier = Modifier.fillMaxSize()) {            // Photo preview - top ~60%            Box(                modifier = Modifier                    .fillMaxWidth()                    .weight(0.6f),                contentAlignment = Alignment.Center            ) {                if (state.error != null) {                    Text(                        state.error,                        color = MaterialTheme.colorScheme.error,                        textAlign = TextAlign.Center,                        modifier = Modifier.padding(16.dp)                    )                } else {                    AsyncImage(                        model = state.imageUri,                        contentDescription = "Selected photo",                        modifier = Modifier.fillMaxSize(),                        contentScale = ContentScale.Fit                    )                }            }            // Bottom panel            Column(                modifier = Modifier                    .fillMaxWidth()                    .weight(0.35f)                    .padding(horizontal = 12.dp, vertical = 8.dp)                    .navigationBarsPadding(),                verticalArrangement = Arrangement.SpaceBetween            ) {                // Auto Button Full Restore                Button(                    onClick = { onEvent(RestoreUiEvent.OneButtonFullRestore) },                    modifier = Modifier                        .fillMaxWidth()                        .height(40.dp),                    shape = RoundedCornerShape(10.dp)                ) {                    Text(                        "Auto Restore",                        fontSize = 14.sp,                        fontWeight = FontWeight.Bold                    )                }                Text(                    text = "To use Auto Restore, choose any one or all of the options below then click Restore.",                    fontSize = 11.sp,                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),                    textAlign = TextAlign.Center,                    modifier = Modifier.fillMaxWidth()                )                // Individual model toggles                Row(                    modifier = Modifier.fillMaxWidth(),                    horizontalArrangement = Arrangement.spacedBy(8.dp, Alignment.CenterHorizontally)                ) {                    FilterChip(                        selected = state.config.denoisingEnabled,                        onClick = { onEvent(RestoreUiEvent.ToggleDenoise) },                        label = { Text("Denoise", fontSize = 12.sp) },                        colors = FilterChipDefaults.filterChipColors(                            selectedContainerColor = Color(0xFF1976D2),                            selectedLabelColor = Color.White                        )                    )                    FilterChip(                        selected = state.config.colorizeEnabled,                        onClick = { onEvent(RestoreUiEvent.ToggleColorize) },                        label = { Text("Colorize", fontSize = 12.sp) },                        colors = FilterChipDefaults.filterChipColors(                            selectedContainerColor = Color(0xFF1976D2),                            selectedLabelColor = Color.White                        )                    )                    FilterChip(                        selected = state.config.faceRestoreEnabled,                        onClick = { onEvent(RestoreUiEvent.ToggleFaceRestore) },                        label = { Text("Face Restore", fontSize = 12.sp) },                        colors = FilterChipDefaults.filterChipColors(                            selectedContainerColor = Color(0xFF1976D2),                            selectedLabelColor = Color.White                        )                    )                    FilterChip(                        selected = state.config.upscalingEnabled,                        onClick = { onEvent(RestoreUiEvent.ToggleUpscale) },                        label = { Text("Upscale", fontSize = 12.sp) },                        colors = FilterChipDefaults.filterChipColors(                            selectedContainerColor = Color(0xFF1976D2),                            selectedLabelColor = Color.White                        )                    )                }                HorizontalDivider()                // Back + Advanced + Restore buttons                Row(                    modifier = Modifier.fillMaxWidth(),                    horizontalArrangement = Arrangement.SpaceBetween,                    verticalAlignment = Alignment.CenterVertically                ) {                    OutlinedButton(onClick = onBack) {                        Text(                            "Back",                            fontSize = 13.sp,                            fontWeight = FontWeight.Medium                        )                    }                    OutlinedButton(onClick = { onEvent(RestoreUiEvent.ShowAdvancedSheet) }) {                        Text(                            "Advanced",                            fontSize = 13.sp,                            fontWeight = FontWeight.Medium                        )                        Spacer(modifier = Modifier.width(2.dp))                        Icon(                            imageVector = Icons.Default.ArrowDropDown,                            contentDescription = "Open advanced settings",                            modifier = Modifier.size(16.dp)                        )                    }                    Button(                        onClick = { onEvent(RestoreUiEvent.ClickRestore) },                        enabled = !state.isProcessing,                        shape = RoundedCornerShape(12.dp),                        modifier = Modifier.height(42.dp),                        colors = ButtonDefaults.buttonColors(                            containerColor = MaterialTheme.colorScheme.primary                        )                    ) {                        Text(                            "Restore",                            fontSize = 15.sp,                            fontWeight = FontWeight.Bold                        )                    }                }            }        }        // Processing overlay        if (state.isProcessing) {            ProcessingOverlay(                progress = state.progress,                config = state.config,            ) { onEvent(RestoreUiEvent.CancelProcessing) }        }    }    if (state.showAdvancedSheet) {        AdvancedSettingsSheet(            initialConfig = state.config,            onDismiss = { onEvent(RestoreUiEvent.DismissAdvancedSheet) },        ) { config -> onEvent(RestoreUiEvent.ApplyAdvancedConfig(config)) }    }}private data class ModelStep(    val name: String,    val subtitle: String,    val enabled: Boolean,)private enum class StepState {    WAITING, PROCESSING, COMPLETE}@Composableprivate fun ProcessingOverlay(    progress: Float,    config: RunConfig,    onCancel: () -> Unit) {    val steps = remember(config) {        listOf(            ModelStep("SCUNet", "Denoise", config.denoisingEnabled),            ModelStep("DDColor", "Colorize", config.colorizeEnabled),            ModelStep("CodeFormer", "Face Restore", config.faceRestoreEnabled),            ModelStep("RealESRGAN", "Upscale", config.upscalingEnabled)        )    }    val enabledSteps = steps.filter { it.enabled }    Box(        modifier = Modifier            .fillMaxSize()            .background(Color.Black.copy(alpha = 0.5f)),        contentAlignment = Alignment.Center    ) {        Card(            modifier = Modifier                .padding(32.dp)                .fillMaxWidth(),            shape = RoundedCornerShape(16.dp),            colors = CardDefaults.cardColors(                containerColor = MaterialTheme.colorScheme.surface            )        ) {            Column(                modifier = Modifier                    .fillMaxWidth()                    .padding(24.dp),                horizontalAlignment = Alignment.CenterHorizontally            ) {                Text(                    text = "Restoring your photo\u2026",                    fontSize = 18.sp,                    fontWeight = FontWeight.Bold                )                Spacer(modifier = Modifier.height(20.dp))                steps.forEach { step ->                    val status = if (!step.enabled) StepState.COMPLETE                    else {                        val idx = enabledSteps.indexOf(step)                        val total = enabledSteps.size                        val stepStart = idx.toFloat() / total                        val stepEnd = (idx + 1).toFloat() / total                        when {                            progress >= stepEnd -> StepState.COMPLETE                            progress >= stepStart -> StepState.PROCESSING                            else -> StepState.WAITING                        }                    }                    Row(                        modifier = Modifier                            .fillMaxWidth()                            .padding(vertical = 4.dp),                        verticalAlignment = Alignment.CenterVertically                    ) {                        when (status) {                            StepState.COMPLETE -> {                                Icon(                                    imageVector = Icons.Default.CheckCircle,                                    contentDescription = "Complete",                                    tint = MaterialTheme.colorScheme.primary,                                    modifier = Modifier.size(20.dp)                                )                            }                            StepState.PROCESSING -> {                                CircularProgressIndicator(                                    modifier = Modifier.size(20.dp),                                    strokeWidth = 2.dp                                )                            }                            StepState.WAITING -> {                                Icon(                                    imageVector = Icons.Outlined.Circle,                                    contentDescription = "Waiting",                                    tint = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.4f),                                    modifier = Modifier.size(20.dp)                                )                            }                        }                        Spacer(modifier = Modifier.width(10.dp))                        Text(                            text = step.name,                            fontSize = 14.sp,                            fontWeight = FontWeight.Medium,                            color = if (status == StepState.WAITING)                                MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.4f)                            else MaterialTheme.colorScheme.onSurface                        )                        Spacer(modifier = Modifier.weight(1f))                        Text(                            text = step.subtitle,                            fontSize = 12.sp,                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(                                alpha = if (status == StepState.WAITING) 0.3f else 0.6f                            )                        )                    }                }                Spacer(modifier = Modifier.height(16.dp))                LinearProgressIndicator(                    progress = { progress },                    modifier = Modifier                        .fillMaxWidth()                        .height(6.dp)                )                Spacer(modifier = Modifier.height(4.dp))                Text(                    text = "${(progress * 100).toInt()}%",                    fontSize = 13.sp,                    color = MaterialTheme.colorScheme.onSurfaceVariant                )                Spacer(modifier = Modifier.height(16.dp))                OutlinedButton(onClick = onCancel) {                    Text("Cancel")                }            }        }    }}